package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.apache.commons.compress.archivers.ArchiveOutputStream;
import org.apache.commons.compress.archivers.tar.TarArchiveEntry;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarArchiveOutputStream_finish_TriageGen2Test {

    @Test
    public void testFinishSuccessfully() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);

        // Create an entry to ensure the stream is in a valid state for finishing
        TarArchiveEntry entry = new TarArchiveEntry("test.txt");
        taos.putArchiveEntry(entry);
        taos.write("content".getBytes());
        taos.closeArchiveEntry();

        // Execute finish
        taos.finish();

        // Verify that the output contains data (EOF records are written)
        byte[] result = baos.toByteArray();
        Assert.assertTrue("Output should not be empty after finish()", result.length > 0);

        taos.close();
    }

    @Test
    public void testFinishWithNoEntries() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);

        // Execute finish on an empty archive
        taos.finish();

        // Verify that even with no entries, EOF records are written
        byte[] result = baos.toByteArray();
        Assert.assertTrue("Output should contain EOF records even if empty", result.length > 0);

        taos.close();
    }

    @Test(expected = IOException.class)
    public void testFinishWithClosedStream() throws IOException {
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        TarArchiveOutputStream taos = new TarArchiveOutputStream(baos);

        taos.close();

        // Attempting to finish after close should trigger an IOException from the underlying stream
        taos.finish();
    }
}
